/* part:page.script.preview.kit.redline */
/* The catalog's live preview of kit.redline. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;

P['kit.redline'] = ({ samples }) => {
  const d = first(samples, 'redline');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const [mode, setMode] = useState('inline');
  const [after, setAfter] = useState(c.after);
  const box = useRef(null), rl = useRef(null);
  const [st, setSt] = useState(null);
  useEffect(() => { setAfter(c.after); }, [id]);
  useEffect(() => {
    rl.current = K().redline.mount(box.current, { before: c.before, after: c.after, mode, labels: c.labels, by: c.by });
    setSt(rl.current.stats);
    return () => rl.current.destroy();
  }, [id]);
  useEffect(() => { setSt(rl.current.update({ after, mode }).stats); }, [after, mode]);
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <div class="pv-row" role="group" aria-label="Mode"><span class="pv-label">Mode</span>${['inline', 'split'].map(m => html`<button type="button" key=${m} class=${'pv-btn' + (mode === m ? ' pri' : '')} aria-pressed=${mode === m} onClick=${() => setMode(m)}>${m}</button>`)}</div>
    <div ref=${box}></div>
    <label class="pv-field"><span>${c.labels[1]}: edit it and the markup follows${c.by === 'char' ? ' (compared letter by letter)' : ''}</span>
      <textarea style="width:100%;min-height:90px;font:14px/1.5 var(--f-ui);color:var(--ink);background:var(--panel);border:1px solid var(--rule);border-radius:8px;padding:8px 10px" value=${after} onInput=${e => setAfter(e.target.value)}></textarea></label>
    ${st ? html`<p class="pv-label">stats(): ${JSON.stringify(st)}</p>` : ''}
  </div>`;
};
})();
/* /part:page.script.preview.kit.redline */

/* part:page.style.kit.redline */
/* Kit css: Redline    kit version 0.1.0    pairs with kit/redline.js
   Removed text struck through in --danger on its soft tint, added text underlined in --ok on its soft tint: the marks read without colour too.
   Needs from the board: --ink --ink-3 --rule --ok --ok-soft --danger --danger-soft --f-ui --f-mono. */
.kit-rl { font-family: var(--f-ui); color: var(--ink); min-width: 0; }
.kit-rl-text { white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.6; }
.kit-rl ins.kit-rl-ins, ins.kit-rl-ins { background: var(--ok-soft); color: var(--ok); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.kit-rl del.kit-rl-del, del.kit-rl-del { background: var(--danger-soft); color: var(--danger); text-decoration: line-through; text-decoration-thickness: 1px; }
.kit-rl-stats { font: 12.5px/1.4 var(--f-mono); color: var(--ink-3); margin-bottom: 6px; }
.kit-rl-n-ins { color: var(--ok); } .kit-rl-n-del { color: var(--danger); margin-left: 8px; }
.kit-rl-split { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px; }
.kit-rl-split > div { min-width: 0; padding-left: 12px; border-left: 1px solid var(--rule); }
.kit-rl-head { font-variant-caps: all-small-caps; letter-spacing: .04em; color: var(--ink-3); margin-bottom: 4px; }
@media (max-width: 640px) { .kit-rl-split { grid-template-columns: minmax(0, 1fr); } }
/* /part:page.style.kit.redline */

/**
 * Redline
 * Kit.redline compares two versions of a text the way a lawyer marks up a draft: words struck through in red where they went, underlined in green where they came in, whitespace kept. Kit.redline.diff gives the operations, Kit.redline.html the escaped markup, and Kit.redline.mount draws it into an element inline or side by side, with a count of words added and removed. Numbers and amounts are compared as whole tokens, so "TWO (1)" to "ONE (1)" marks the word, not the letters.
 *
 * What it is: the comparison every edited clause, proposed wording and version history needs. A longest-common-subsequence over word and whitespace tokens, after trimming the
 * common head and tail, so a one-word change in a long clause costs almost nothing. Above a size limit it falls back to "all removed, all added" rather than freeze the page.
 * Every string is escaped; a diff can show any text safely.
 * API (small and stable):
 *   Kit.redline.diff(a, b, {by = 'word', limit = 4e6}) -> [[op, text], ...]   op is '=' kept, '-' removed, '+' added; by 'char' compares characters
 *   Kit.redline.html(ops) -> string                 <span>kept</span>, <del class="kit-rl-del">, <ins class="kit-rl-ins">, all text escaped
 *   Kit.redline.stats(ops) -> {added, removed, kept} counted in words
 *   Kit.redline.mount(el, {before, after, mode = 'inline', stats = true, labels = ['Before', 'After'], by}) -> {ops, stats, update(opts), destroy()}
 *     update(opts) merges the options (a new after, another mode) and redraws; destroy() empties el
 *     mode 'inline' one column with both marks; 'split' the old text with its removals beside the new text with its additions
 *
 * @id        kit.redline
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.2.0
 * @updated   2026-11-20
 * @summary   A lawyer's markup of two versions: removed words struck in red, added words underlined in green, inline or side by side, with word counts; all text escaped.
 * @tags      diff, redline, compare, versions, track changes, markup, contract, policy, release notes, history
 * @requires  none
 * @files     kit/redline.css, kit/samples/redline.json, kit/previews/redline.js
 * @provides  Kit.redline.diff, Kit.redline.html, Kit.redline.stats, Kit.redline.mount
 * @config    Kit.redline.mount(el, opts) | before, after (the two texts), mode (inline or split), stats (true shows the count line), labels (the two column heads), by (word or char)
 * @config    Kit.redline.diff(a, b, opts) | by (word or char), limit (cells of the comparison table before the fallback, default 4e6)
 * @tokens    --ink --ink-3 --rule --ok --ok-soft --danger --danger-soft --f-ui --f-mono
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-19 | an agreement review board | clause history, proposed wording and the version-to-version redline
 * @preview   {"render": "kit.redline", "samples": ["kit/samples/redline.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const tokens = (s, by) => by === 'char' ? Array.from(s || '') : ((s || '').match(/\s+|[^\s]+/g) || []);

function diff(a, b, { by = 'word', limit = 4e6 } = {}) {
  const ta = tokens(a, by), tb = tokens(b, by);
  let head = 0; while (head < ta.length && head < tb.length && ta[head] === tb[head]) head++;
  let tail = 0; while (tail < ta.length - head && tail < tb.length - head && ta[ta.length - 1 - tail] === tb[tb.length - 1 - tail]) tail++;
  const A = ta.slice(head, ta.length - tail), B = tb.slice(head, tb.length - tail);
  const ops = [];
  const push = (op, s) => { if (!s) return; const l = ops[ops.length - 1]; if (l && l[0] === op) l[1] += s; else ops.push([op, s]); };
  push('=', ta.slice(0, head).join(''));
  const n = A.length, m = B.length;
  if (n * m > limit) { push('-', A.join('')); push('+', B.join('')); }
  else {
    const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
    for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = A[i] === B[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    let i = 0, j = 0;
    while (i < n && j < m) {
      if (A[i] === B[j]) { push('=', A[i]); i++; j++; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) push('-', A[i++]);
      else push('+', B[j++]);
    }
    while (i < n) push('-', A[i++]);
    while (j < m) push('+', B[j++]);
  }
  push('=', ta.slice(ta.length - tail).join(''));
  // a change that is only whitespace between two changes reads better inside them
  for (let k = 1; k < ops.length - 1; k++) {
    if (ops[k][0] === '=' && /^\s+$/.test(ops[k][1]) && ops[k - 1][0] !== '=' && ops[k + 1][0] !== '=') {
      const s = ops[k][1]; ops.splice(k, 1, ['-', s], ['+', s]);
    }
  }
  const out = []; // merge neighbours again, removals before additions
  for (let k = 0; k < ops.length; k++) {
    if (ops[k][0] === '=') { out.push(ops[k]); continue; }
    let del = '', ins = ''; while (k < ops.length && ops[k][0] !== '=') { if (ops[k][0] === '-') del += ops[k][1]; else ins += ops[k][1]; k++; } k--;
    if (del) out.push(['-', del]); if (ins) out.push(['+', ins]);
  }
  return out;
}

const html = ops => ops.map(([op, s]) => op === '=' ? `<span>${esc(s)}</span>` : op === '+' ? `<ins class="kit-rl-ins">${esc(s)}</ins>` : `<del class="kit-rl-del">${esc(s)}</del>`).join('');
const words = s => (s.match(/\S+/g) || []).length;
function stats(ops) {
  const r = { added: 0, removed: 0, kept: 0 };
  ops.forEach(([op, s]) => { r[op === '+' ? 'added' : op === '-' ? 'removed' : 'kept'] += words(s); });
  return r;
}

function render(el, a, b, { mode = 'inline', stats: showStats = true, labels = ['Before', 'After'], by } = {}) {
  const ops = diff(a, b, { by }), st = stats(ops);
  el.classList.add('kit-rl');
  let body;
  if (mode === 'split') {
    const left = ops.filter(o => o[0] !== '+'), right = ops.filter(o => o[0] !== '-');
    body = `<div class="kit-rl-split"><div><div class="kit-rl-head">${esc(labels[0])}</div><div class="kit-rl-text">${html(left)}</div></div>
      <div><div class="kit-rl-head">${esc(labels[1])}</div><div class="kit-rl-text">${html(right)}</div></div></div>`;
  } else body = `<div class="kit-rl-text">${html(ops)}</div>`;
  const line = !showStats ? '' : (st.added || st.removed)
    ? `<div class="kit-rl-stats"><span class="kit-rl-n-ins">+${st.added} word${st.added === 1 ? '' : 's'}</span> <span class="kit-rl-n-del">−${st.removed} word${st.removed === 1 ? '' : 's'}</span></div>`
    : `<div class="kit-rl-stats">No change.</div>`;
  el.innerHTML = line + body;
  return { ops, stats: st };
}

function mount(el, opts = {}) {
  let o = { ...opts }, last;
  const draw = () => (last = render(el, o.before || '', o.after || '', o));
  draw();
  return {
    get ops() { return last.ops; },
    get stats() { return last.stats; },
    update(next = {}) { o = { ...o, ...next }; return draw(); },
    destroy() { el.classList.remove('kit-rl'); el.replaceChildren(); },
  };
}

Kit.redline = Object.freeze({ diff, html, stats, mount });
})();

